import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.6vsupRmR.js";const p=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),i={name:"roadmap.md"};function n(l,e,s,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Arkel is in active, early development. The main instance of the network is scheduled to go live soon.</p><h2 id="now-a-working-core-network" tabindex="-1">Now: A working core network <a class="header-anchor" href="#now-a-working-core-network" aria-label="Permalink to &quot;Now: A working core network&quot;">​</a></h2><ul><li>Erasure-coded (k/m) object storage with client-side encryption</li><li>Raft-based index cluster (membership, quotas, ownership)</li><li>Storage nodes: registration/heartbeat, GC of unreferenced shards</li><li>Integrity: health checks, shard audits, automatic repair &amp; redistribution</li></ul><h2 id="next-an-economy-for-contributors" tabindex="-1">Next: An economy for contributors <a class="header-anchor" href="#next-an-economy-for-contributors" aria-label="Permalink to &quot;Next: An economy for contributors&quot;">​</a></h2><ul><li><strong>Credits &amp; quotas</strong> — accounts buy credit to store; usage debits against it</li><li><strong>Contribution grants</strong> — storage operators earn credit for the bytes they host</li><li><strong>Payouts</strong> — settle node operators in USDC</li><li>Operator dashboard — see your capacity, usage, and earnings</li></ul><h2 id="then-drop-in-compatibility" tabindex="-1">Then: Drop-in compatibility <a class="header-anchor" href="#then-drop-in-compatibility" aria-label="Permalink to &quot;Then: Drop-in compatibility&quot;">​</a></h2><ul><li><strong>S3-compatible gateway</strong> — use Arkel from existing tools (rclone, restic, the AWS SDK) instead of only the <code>arkel</code> CLI</li><li>Replication/import tooling to migrate off a cloud provider</li></ul><h2 id="later-more-good-stuff" tabindex="-1">Later: More good stuff <a class="header-anchor" href="#later-more-good-stuff" aria-label="Permalink to &quot;Later: More good stuff&quot;">​</a></h2><ul><li>Public node discovery &amp; reputation (who is fast, reliable, well-connected)</li><li>Node-vetted payout scaling and market-based pricing</li></ul><p>This is a rough order, the roadmap will be largely driven by what contributors actually need.</p>',11)])])}const m=o(i,[["render",n]]);export{p as __pageData,m as default};
